(* [comment removed for export] *)
Definition isl_Wl (lo : Z) (sp : word) (P IN E : Z) : list (Z * Z) :=
  [(lo, bv_unsigned sp); (P, P + 80); (IN, IN + 8); (E, E + 24); (AG_HTTP_CAT, AG_HTTP_CAT + 64)]%Z.

(* [comment removed for export] *)
Definition isl_side (m : mem) (P E p0 n lo shi : Z) : Prop := pside2 m lo shi [(p0, n); (E, 24); (P, 256)] [(p0, n); (E, 24)].

Definition isl_sv (s11 s10 s9 s8 s7 s6 s5 s4 s3 s2 s1 s0 ra : word) : list cell :=
  [C8 s11; C8 s10; C8 s9; C8 s8; C8 s7; C8 s6; C8 s5; C8 s4; C8 s3; C8 s2; C8 s1; C8 s0; C8 ra].

(* [comment removed for export] *)
Definition isl_ctx (m m1 : mem) (sp : word) (SV : list cell) (P IN E lo shi : Z) (c : pcore) (pad7 pad2 : list byte)
    (p0 : Z) (bs : list byte) (h : hdrv) (lowc verc : list cell) (itv : Z) (tmp ecs : list cell) (g : bool) : Prop :=
  rw_cells asegs m1 (bv_unsigned sp + -160) lowc
  /\ rw_cells asegs m1 (bv_unsigned sp + -144) verc
  /\ rw_cells asegs m1 (bv_unsigned sp + -136) [C8 (wz itv)]
  /\ rw_cells asegs m1 (bv_unsigned sp + -128) tmp
  /\ rw_cells asegs m1 (bv_unsigned sp + -104) SV
  /\ rw_cells asegs m1 P (ParserCoreCells c pad7 pad2)
  /\ rw_cells asegs m1 IN [C8 (wz p0)]
  /\ rw_cells asegs m1 E ecs
  /\ rw_cells asegs m1 (P + O_PR_USED) [C1 (b8 0)]
  /\ rw_cells asegs m1 (P + O_PR_HDR) (HdrCells h)
  /\ bytes_at asegs m1 p0 bs
  /\ AHttpCat m1 g
  /\ stk asegs m1 lo (bv_unsigned sp + -160)
  /\ munch (isl_Wl lo sp P IN E) m m1 /\ wmono asegs m m1 /\ mem_inv asegs m1
  /\ isl_side m P E p0 (Z.of_nat (length bs)) lo shi.

(* [comment removed for export] *)
Definition isl_pureA (sp : word) (P IN E lo shi : Z) (c : pcore) (p0 : Z) (bs : list byte) (h : hdrv) : Prop :=
  isl_pure sp P IN E lo shi c p0 bs /\ aapp P 256 /\ aapp E 24 /\ aapp p0 (Z.of_nat (length bs)) /\ 0 <= P /\ hdr_empty h.

(* [comment removed for export] *)
Definition isl_ret_post (ra sp gp tp s0 s1 s2 s3 s4 s5 s6 s7 s8 s9 s10 s11 : word) (F : bvmap 5 word) (fc : bv 32)
    (P IN E lo shi : Z) (c : pcore) (pad7 pad2 : list byte) (p0 : Z) (bs : list byte) (h : hdrv) (m : mem) : machine_state -> Prop :=
  fun ms' => exists t0 t1 t2 a0 a1 a2 a3 a4 a5 a6 a7 t3 t4 t5 t6 m' e loc,
    ms' = MS (mkR ra sp gp tp t0 t1 t2 s0 s1 a0 a1 a2 a3 a4 a5 a6 a7 s2 s3 s4 s5 s6 s7 s8 s9 s10 s11 t3 t4 t5 t6)
             F (ret_pc ra) fc None m' (seg_rom asegs)
    /\ munch (isl_Wl lo sp P IN E) m m' /\ wmono asegs m m' /\ mem_inv asegs m'
    /\ stk asegs m' lo (bv_unsigned sp)
    /\ rw_cells asegs m' P (ParserCoreCells c pad7 pad2)
    /\ rw_cells asegs m' IN [C8 (wz p0)]
    /\ rw_cells asegs m' E (ErrCodeCells (EC_http_loc e loc))
    /\ In e [HE_NEED_MORE; HE_BAD_METHOD; HE_BAD_TARGET; HE_BAD_VERSION] /\ Z.even loc = true /\ 4 <= loc /\ loc + 1 < 2^64
    /\ rw_cells asegs m' (P + O_PR_USED) [C1 (b8 0)]
    /\ rw_cells asegs m' (P + O_PR_HDR) (HdrCells h)
    /\ bytes_at asegs m' p0 bs
    /\ AHttpCat m' true /\ isl_side m' P E p0 (Z.of_nat (length bs)) lo shi.

Lemma isl_pwin : forall sp P IN E lo shi c p0 bs h, isl_pureA sp P IN E lo shi c p0 bs h -> Forall pwin (isl_Wl lo sp P IN E).
Proof.
  intros sp P IN E lo shi c p0 bs h ((_ & _ & LO & CEIL & _ & _ & ILO & _) & APP & APE & _).
  unfold isl_Wl. repeat apply Forall_cons; [| | | | | apply Forall_nil].
  - apply pwin_stack. exact CEIL.
  - eapply pwin_aapp; [exact APP| clear; lia| clear; lia].
  - apply pwin_stack. unfold ISL_STACK, ONREQ_STACK, AHDRMETHOD_STACK, AREALLOC_STACK, AOPNEW_STACK, AMALLOC_STACK in LO. clear - CEIL LO ILO. lia.
  - eapply pwin_aapp; [exact APE| clear; lia| clear; lia].
  - exact pwin_httpcat.
Qed.

(* [comment removed for export] *)
Definition isl_exit_stmt (k : nat) (pc e loc : Z) : Prop :=
  forall rax ra sp gp tp t0 t1 t2 a0 a1 a2 a3 a4 a5 a6 a7 s3x s5x s6x s7x s8x s11x
         s11v s10v s9v s8v s7v s6v s5v s4v s3v s2v s1v s0v t3 t4 t5 t6
    (F : bvmap 5 word) fc (m m1 : mem) (P IN E lo shi : Z) (c : pcore) (pad7 pad2 : list byte) (p0 : Z) (bs : list byte) (h : hdrv)
    (lowc verc : list cell) (itv : Z) (ecs : list cell) (g : bool) (j24 : list byte),
  isl_ctx m m1 sp (isl_sv s11v s10v s9v s8v s7v s6v s5v s4v s3v s2v s1v s0v ra) P IN E lo shi c pad7 pad2 p0 bs h
          lowc verc itv [CB 24 j24] ecs g ->
  isl_pureA sp P IN E lo shi c p0 bs h -> cells_size lowc = 16%nat -> cells_size verc = 8%nat -> cells_size ecs = 24%nat -> 0 <= itv < 2^64 ->
  evt asegs (isl_ret_post ra sp gp tp s0v s1v s2v s3v s4v s5v s6v s7v s8v s9v s10v s11v F fc P IN E lo shi c pad7 pad2 p0 bs h m)
    (MS (mkR rax (Z_to_bv 64 (bv_unsigned sp + -160)) gp tp t0 t1 t2 (wz (E + 16)) (wz E) a0 a1 a2 a3 a4 a5 a6 a7
              (wz IN) s3x (wz (p0 + Z.of_nat (length bs))) s5x s6x s7x s8x (wz 2147450880) (wz (Z.shiftr IN 3 + 2147450880))
              (kpick k 0 s11x (wz (Z.shiftr (E + 16) 3 + 2147450880))) t3 t4 t5 t6)
        F (Z_to_bv 64 pc) fc None m1 (seg_rom asegs)).
End CTXDEF.

(* [comment removed for export] *)
Ltac isl_rfinish e loc :=
  apply evt_done; unfold isl_ret_post;
  do 16 eexists; exists e, loc;
  split; [reflexivity|]; repeat match goal with |- _ /\ _ => split end; try assumption; try lia.

(* [comment removed for export] *)
Ltac open_isl CTX PURE :=
  destruct CTX as (FRlo & VERC & IT & TMP & FRhi & PC & INC & EC & USED & HDR & WIN & HC & ST & MU & WM & MI & SIDE);
  pose proof (isl_pwin _ _ _ _ _ _ _ _ _ _ PURE) as FW;
  destruct PURE as ((PCOK & NB & LO & CEIL & PAL & EAL & ILO & IHI & IAL & DPE & DWP & DWE & SPAL & SHI) & APP & APE & APW & P0 & HE);
  let LOB := fresh "LOB" in
  lazymatch type of LO with ?l + ISL_STACK <= bv_unsigned ?s =>
    assert (LOB : l + 4304 <= bv_unsigned s) by (unfold ISL_STACK, ONREQ_STACK, AHDRMETHOD_STACK, AREALLOC_STACK, AOPNEW_STACK, AMALLOC_STACK in LO; clear - LO; lia) end;
  pose proof (ex_bnd_intro 4304 _ _ _ _ LOB CEIL SHI APE) as BND; clear LOB;
  pose proof BND as BNDv; unfold ex_bnd in BNDv; destruct BNDv as (_ & _ & _ & SPR & EB1 & EB2 & EB3 & EB4 & AF1);
  pose proof (stack0_bounds _ _ _ (pside2_stack0 _ _ _ _ _ SIDE)) as [SKB1 SKB2];
  pose proof (aapp_bounds _ 256 APP ltac:(lia)) as (PB1 & PB2 & PB3 & PB4 & PB5);
  pose proof (bytes_at_bound _ _ _ _ WIN) as WB;
  pose proof (aapp_bounds _ _ APW ltac:(lia)) as (WB1 & WB2 & WB3 & WB4 & WB5);
  clear PB5 WB5; hydeL DPE; hydeL DWP; hydeL DWE; hydeL EAL; hydeL SPAL;
  unfold isl_Wl, isl_sv, ISL_STACK, ONREQ_STACK, AHDRMETHOD_STACK, AREALLOC_STACK, AOPNEW_STACK, AMALLOC_STACK, AASSIGN_STACK, AINTRIN_STACK,
         AG_HTTP_CAT, AAPP_HI, AIMG_TOP, O_PR_USED, O_PR_HDR in *;
  unfold ParserCoreCells in PC; cbn [pc_blim_has pc_blim pc_len pc_len0 pc_skip pc_hlim pc_state pc_f] in PC;
  try (unfold ErrCodeCells in EC; cbn [ec_val ec_cat ec_flags] in EC); unfold HdrCells in HDR; cbn [hv_mp hv_ml hv_tp hv_tl hv_ver hv_vb] in HDR;
  unfold wz in *.

(* [comment removed for export] *)
Ltac isl_rectx SIDE :=
  unfold isl_ctx, isl_Wl, isl_sv, AG_HTTP_CAT, O_PR_USED, O_PR_HDR, ParserCoreCells, wz; cbn [pc_blim_has pc_blim pc_len pc_len0 pc_skip pc_hlim pc_state pc_f];
