(* [comment removed for export] *)
Ltac isl_exit_script MEMCPY ASSIGNA k e loc CHK :=
  unfold isl_exit_stmt;
  intros rax ra sp gp tp t0 t1 t2 a0 a1 a2 a3 a4 a5 a6 a7 s3x s5x s6x s7x s8x s11x
         s11v s10v s9v s8v s7v s6v s5v s4v s3v s2v s1v s0v t3 t4 t5 t6
         F fc m m1 P IN E lo shi c pad7 pad2 p0 bs h lowc verc itv ecs g j24;
  intros CTX PURE SZL SZV SZE ITV;
  destruct CTX as (FRlo & VERC & IT & TMP & FRhi & PC & INC & EC & USED & HDR & WIN & HC & ST & MU & WM & MI & SIDE);
  pose proof (isl_pwin _ _ _ _ _ _ _ _ _ _ PURE) as FW;
  destruct PURE as ((PCOK & NB & LO & CEIL & PAL & EAL & ILO & IHI & IAL & DPE & DWP & DWE & SPAL & SHI) & APP & APE & APW & P0 & HE);
  let LOB := fresh "LOB" in
  lazymatch type of LO with ?l + ISL_STACK <= bv_unsigned ?s =>
    assert (LOB : l + 4304 <= bv_unsigned s) by (unfold ISL_STACK, ONREQ_STACK, AHDRMETHOD_STACK, AREALLOC_STACK, AOPNEW_STACK, AMALLOC_STACK in LO; clear - LO; lia) end;
  pose proof (ex_bnd_intro 4304 _ _ _ _ LOB CEIL SHI APE) as BND; clear LOB;
  pose proof BND as BNDv; unfold ex_bnd in BNDv; destruct BNDv as (_ & _ & _ & SPR & EB1 & EB2 & EB3 & EB4 & AF1);
  pose proof (stack0_bounds _ _ _ (pside2_stack0 _ _ _ _ _ SIDE)) as [SKB1 SKB2];
  pose proof (aapp_bounds _ 256 APP ltac:(lia)) as (PB1 & PB2 & PB3 & PB4 & PB5);
  pose proof (bytes_at_bound _ _ _ _ WIN) as WB;
  pose proof (aapp_bounds _ _ APW ltac:(lia)) as (WB1 & WB2 & WB3 & WB4 & WB5);
  clear PB5 WB5; hydeL DPE; hydeL DWP; hydeL DWE; hydeL EAL; hydeL SPAL;
  unfold isl_Wl, isl_sv, ISL_STACK, ONREQ_STACK, AHDRMETHOD_STACK, AREALLOC_STACK, AOPNEW_STACK, AMALLOC_STACK, AASSIGN_STACK, AINTRIN_STACK,
         AG_HTTP_CAT, AAPP_HI, AIMG_TOP, O_PR_USED, O_PR_HDR in *;
  unfold ParserCoreCells in PC; cbn [pc_blim_has pc_blim pc_len pc_len0 pc_skip pc_hlim pc_state pc_f] in PC;
  try (unfold ErrCodeCells in EC; cbn [ec_val ec_cat ec_flags] in EC); unfold HdrCells in HDR; cbn [hv_mp hv_ml hv_tp hv_tl hv_ver hv_vb] in HDR;
  unfold wz in *;
  assert (D8 : (bv_unsigned sp + -128) mod 8 = 0) by (clear - SPAL; unfold hideL in SPAL; Z.div_mod_to_equations; lia);
  hydeL D8; unfold kpick; cbn [Nat.eqb];
  (* [comment removed for export] *)
  pose proof (munch_refl [(lo, bv_unsigned sp); (E, E + 24); (6667152, 6667152 + 64)]%Z m1) as MUx;
  pose proof (wmono_refl asegs m1) as WMx;
  park USED; park HDR; park WIN; park INC; park PC;
  destruct (rw_cells_forget _ _ _ _ EC) as [ej EC2]; rewrite SZE in EC2; clear EC;
  assign_loc_core MEMCPY ASSIGNA SIDE MU WM FW HC TMP EC2 ST MI APE D8 BND (bv_unsigned sp + -128) E e loc lo shi sp g j24 ej m;
  assign_loc_chk SIDE FW EAL E m CHK;
  (* [comment removed for export] *)
  let KQ := fresh "KQ" in
  lazymatch k with
  | 0%nat => (* [comment removed for export] *)
      step; step; st1;
      assign_loc_chk SIDE FW EAL E m ltac:(zstep; zstep; step);
      step; zstep; step; if_cases KQ; zify_cond KQ; [clear KQ| exfalso; rewrite ?unsigned_lit in KQ by (clear; lia); clear - KQ; lia];
      step; step; if_cases KQ; zify_cond KQ;
      [clear KQ| exfalso; rewrite ?unsigned_lit in KQ by (clear; lia); clear - KQ; lia]
  | 1%nat => (* [comment removed for export] *)
      step; step; st1;
      zstep; step; if_cases KQ; zify_cond KQ; [clear KQ| exfalso; rewrite ?unsigned_lit in KQ by (clear; lia); clear - KQ; lia];
      step; step; if_cases KQ; zify_cond KQ;
      [clear KQ| exfalso; rewrite ?unsigned_lit in KQ by (clear; lia); clear - KQ; lia]
  | _ => (* [comment removed for export] *)
      st1
  end;
  (* [comment removed for export] *)
  do 13 step;
  lazymatch goal with
  | FRl : rw_cells _ _ (bv_unsigned sp + -160) _, VR : rw_cells _ _ (bv_unsigned sp + -144) _, ITc : rw_cells _ _ (bv_unsigned sp + -136) _,
    TMPa : rw_cells _ _ (bv_unsigned sp + -128) [C8 _; C8 _], TMPb : rw_cells _ _ (bv_unsigned sp + -112) [C8 _],
    FRh : rw_cells _ _ (bv_unsigned sp + -104) _, ST3 : stk _ _ _ (bv_unsigned sp + -160) |- _ =>
      let j1 := fresh "jl" in let F1 := fresh "FRl1" in let j2 := fresh "jv" in let F2 := fresh "VR1" in
      destruct (rw_cells_forget _ _ _ _ FRl) as [j1 F1]; clear FRl; rewrite SZL in F1;
      destruct (rw_cells_forget _ _ _ _ VR) as [j2 F2]; clear VR; rewrite SZV in F2;
      join_frameA F1 F2 (bv_unsigned sp + -160); join_frameA F1 ITc (bv_unsigned sp + -160);
      join_frameA F1 TMPa (bv_unsigned sp + -160); join_frameA F1 TMPb (bv_unsigned sp + -160); join_frameA F1 FRh (bv_unsigned sp + -160);
      step; release_frame F1 ST3 (bv_unsigned sp)
  end;
  step;
  assign_loc_close SIDE FW BND E e loc m;
